// Lazy windowed / chunked / zipWithNext / running folds (they work on infinite sequences) and the long tail of the sequence operators.
fun main() {
    val nat = generateSequence(1) { it + 1 }
    println(nat.chunked(3).take(2).toList())
    println(nat.windowed(3).take(3).toList())
    println(nat.windowed(2, 3).take(3).toList())
    println(nat.zipWithNext().take(3).toList())
    println(nat.zipWithNext { a, b -> a * b }.take(4).toList())
    println(nat.runningFold(10) { a, b -> a + b }.take(5).toList())
    println(nat.scan(0) { a, b -> a + b }.take(4).toList())
    println(nat.runningReduce { a, b -> a + b }.take(5).toList())
    println(nat.runningFoldIndexed(0) { i, a, b -> a + i * b }.take(4).toList())
    println(nat.scanIndexed(0) { i, a, b -> a + i }.take(4).toList())

    val s = sequenceOf(1, 2, 3, 4, 5)
    println(s.windowed(2, 1, true).toList())
    println(s.windowed(3, 2, true).toList())
    println(s.windowed(3, 2, false).toList())
    println(s.windowed(2, 3, true).toList())
    println(s.windowed(2, 3, false).toList())
    println(s.windowed(7, 1, true).toList())
    println(s.windowed(7, 1).toList())
    println(s.windowed(2) { it.sum() }.toList())
    println(s.chunked(2).toList())
    println(s.chunked(2) { it.joinToString("+") }.toList())
    println(emptySequence<Int>().windowed(2).toList())
    println(emptySequence<Int>().zipWithNext().toList())
    println(emptySequence<Int>().runningFold(1) { a, b -> a + b }.toList())
    println(emptySequence<Int>().runningReduce { a, b -> a + b }.toList())
    println(sequenceOf(4).zipWithNext().toList())
    println(sequenceOf(4).runningReduce { a, b -> a + b }.toList())
    println(s.runningReduce { a, b -> a * b }.toList())
    println(s.runningReduce { a, b -> a + b }.toList())
    println(s.runningFold("") { a, b -> a + b }.toList())
    println("abcdefg".chunkedSequence(3).toList())
    println("abcdefg".windowedSequence(3, 2).toList())
    println("abcdefg".windowedSequence(3, 2, true).toList())
    println("abcdefg".chunkedSequence(2) { it.length }.toList())

    val log = StringBuilder()
    val traced = sequenceOf(1, 2, 3, 4).onEach { log.append("p$it ") }
    val w = traced.windowed(2).iterator()
    println(w.next())
    println(log.toString())
    println(w.next())
    println(log.toString())
    log.setLength(0)
    val z = traced.zipWithNext().iterator()
    println(log.toString().isEmpty())
    println(z.next())
    println(log.toString())
    log.setLength(0)
    val r = traced.runningFold(0) { a, b -> a + b }.iterator()
    println(r.next())
    println(log.toString().isEmpty())
    println(r.next())
    println(log.toString())

    try {
        s.windowed(0)
    } catch (e: IllegalArgumentException) {
        println(e.message)
    }
    try {
        s.chunked(-1)
    } catch (e: IllegalArgumentException) {
        println(e.message)
    }

    val mixed = sequenceOf<Any>(1, "a", 2.5, "b")
    println(mixed.filterIsInstance<String>().toList())
    println(s.indexOfFirst { it > 2 })
    println(s.indexOfLast { it < 4 })
    println(s.lastIndexOf(3))
    println(s.findLast { it < 4 })
    println(s.last { it % 2 == 1 })
    println(s.single { it == 4 })
    println(s.singleOrNull { it > 3 })
    println(s.elementAtOrElse(9) { -it })
    println(s.firstNotNullOf { if (it > 2) it * 10 else null })
    println(s.firstNotNullOfOrNull { if (it > 9) it else null })
    println(s.foldIndexed(0) { i, a, b -> a + i * b })
    println(s.reduceIndexed { i, a, b -> a + i * b })
    println(s.reduceOrNull { a, b -> a + b })
    println(emptySequence<Int>().reduceOrNull { a, b -> a + b })
    println(s.reduceIndexedOrNull { i, a, b -> a + b * i })
    println(s.sumBy { it * 3 })
    println(sequenceOf(1.5f, 2.0f).sum())
    println(sequenceOf<Short>(3, 4).sum())
    println(s.minWith(compareBy<Int> { -it }))
    println(s.maxWith(compareBy<Int> { -it }))
    println(s.maxOfOrNull { it % 3 })
    println(s.minOfOrNull { it % 3 })
    println(s.toSortedSet())
    println(s.flatMapIndexed { i, x -> listOf(i, x) }.toList())
    println(s.mapTo(ArrayList()) { it * 2 })
    println(s.filterTo(ArrayList()) { it > 3 })
    println(s.filterNotTo(ArrayList()) { it > 3 })
    println(s.toCollection(ArrayDeque()))
    println(s.groupingBy { it % 2 }.eachCount())
    println(sequenceOf(1 to "a", 2 to "b").unzip())
    println(s.minus(listOf(2, 3)).toList())
    println(s.minus(sequenceOf(1, 5)).toList())
    println(s.minus(arrayOf(4)).toList())
    var total = 0
    s.iterator().forEach { total += it }
    println(total)
}
